func spawn(task_name: String, body: Callable, on_complete: Callable = Callable()) -> void:
	var task = {
		"id": _tasks.size(),
		"name": task_name,
		"on_complete": on_complete,
		"state": null,
		"finished": false,
		"wait_type": "none",
		"wait_frames": -1,
		"wait_until": Callable(),
		"wait_signal": Signal(),
		"signal_fired": false,
		"signal_receiver": null,
		"signal_receiver_bound_call": null,
		"signal_bound_fired_call": null,
	}
	_tasks.append(task)
	_current_task_id = task["id"]
	var res = body.call()
	_current_task_id = -1

	if res is GDScriptFunctionState and res.is_valid():
		task["state"] = res
	else:
		task["finished"] = true
		_on_task_finished(task)


func wait_frames(n: int) -> void:
	var task = _get_current_task()
	task["wait_type"] = "frames"
	task["wait_frames"] = current_frame + n
	await _suspend_helper()


func wait_until(cond: Callable) -> void:
	var task = _get_current_task()
	task["wait_type"] = "until"
	task["wait_until"] = cond
	await _suspend_helper()


func wait_signal(sig: Signal) -> void:
	var task = _get_current_task()
	task["wait_type"] = "signal"
	task["wait_signal"] = sig
	task["signal_fired"] = false

	var n = _get_signal_arg_count(sig)
	task["signal_receiver"] = _create_signal_receiver(n)

	task["signal_bound_fired_call"] = _on_task_signal_fired.bind(task["id"])
	task["signal_receiver"].fired.connect(task["signal_bound_fired_call"])

	task["signal_receiver_bound_call"] = task["signal_receiver"]._receive.bind(task["id"])
	sig.connect(task["signal_receiver_bound_call"])

	await _suspend_helper()


func advance(frames: int) -> void:
	for _f in range(frames):
		current_frame += 1
		for task in _tasks:
			if task["finished"]:
				continue

			var ready: bool = false
			match task["wait_type"]:
				"frames":
					if task["wait_frames"] <= current_frame:
						ready = true
				"until":
					_current_task_id = task["id"]
					if task["wait_until"].call():
						ready = true
					_current_task_id = -1
				"signal":
					if task["signal_fired"]:
						ready = true
				"none":
					pass  # should not occur for a suspended task

			if ready:
				_resume_task(task)


func _get_signal_arg_count(sig: Signal) -> int:
	var obj = sig.get_object()
	var name = sig.get_name()
	if not obj:
		return 0
	var signals = obj.get_signal_list()
	for s in signals:
		if s.has("name") and s["name"] == name:
			var args = s.get("args")
			if args is Array:
				return args.size()
			return 0
	return 0


func _create_signal_receiver(n: int):
	match n:
		0: return SignalReceiver0.new()
		1: return SignalReceiver1.new()
		2: return SignalReceiver2.new()
		3: return SignalReceiver3.new()
		4: return SignalReceiver4.new()
		5: return SignalReceiver5.new()
		6: return SignalReceiver6.new()
		7: return SignalReceiver7.new()
		8: return SignalReceiver8.new()
		_: return SignalReceiver0.new()  # fallback for larger arity


func _suspend_helper() -> void:
	await _suspend_signal


func _get_current_task():
	if _current_task_id >= 0 and _current_task_id < _tasks.size():
		return _tasks[_current_task_id]
	return null


func _on_task_finished(task):
	if task["on_complete"].is_valid():
		task["on_complete"].call(task["name"])


func _resume_task(task):
	var old_state = task["state"]
	if old_state == null or not old_state.is_valid():
		task["finished"] = true
		_on_task_finished(task)
		return

	_cleanup_wait(task)

	_current_task_id = task["id"]
	var res = old_state.resume()
	_current_task_id = -1

	if res is GDScriptFunctionState and res.is_valid():
		task["state"] = res
	else:
		task["state"] = null
		task["finished"] = true
		_on_task_finished(task)


func _cleanup_wait(task):
	var receiver = task["signal_receiver"]
	if receiver != null:
		var sig = task["wait_signal"]
		var bound_receive = task["signal_receiver_bound_call"]
		if sig.is_valid():
			sig.disconnect(bound_receive)
		var bound_fired = task["signal_bound_fired_call"]
		receiver.fired.disconnect(bound_fired)
		task["signal_receiver"] = null
		task["signal_receiver_bound_call"] = null
		task["signal_bound_fired_call"] = null

	task["wait_type"] = "none"
	task["wait_frames"] = -1
	task["wait_until"] = Callable()
	task["wait_signal"] = Signal()
	task["signal_fired"] = false


func _on_task_signal_fired(task_id: int):
	if task_id >= 0 and task_id < _tasks.size():
		_tasks[task_id]["signal_fired"] = true

